import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import api from '../services/api';

const VILLES = ['Tunis', 'Sfax', 'Sousse', 'Monastir', 'Nabeul', 'Bizerte', 'Kairouan', 'Ariana', 'Ben Arous', 'Mahdia'];
const NIVEAUX_STUDENT = ['Primaire', 'Collège', 'Lycée 1ère', 'Lycée 2ème', 'Lycée 3ème (Bac)', 'Université'];
const MODES = [
  { value: 'en_ligne',   label: '🌐 En ligne',   desc: 'Cours via Zoom, Meet...' },
  { value: 'presentiel', label: '🏫 Présentiel',  desc: 'Cours en face à face' },
  { value: 'les_deux',   label: '🔀 Les deux',    desc: 'En ligne et présentiel' },
];

/* ── Badge statut demande ── */
function StatutBadge({ statut }) {
  const cfg = {
    en_attente: { bg: 'rgba(245,158,11,0.12)', color: '#f59e0b', label: '⏳ En attente' },
    approuvé:   { bg: 'rgba(67,233,123,0.12)',  color: '#43e97b', label: '✅ Approuvée' },
    refusé:     { bg: 'rgba(255,101,132,0.12)', color: '#ff6584', label: '❌ Refusée' },
  }[statut] || { bg: 'var(--surface2)', color: 'var(--text2)', label: statut };
  return (
    <span style={{ fontSize: '.7rem', fontWeight: 700, padding: '3px 10px', borderRadius: 20, background: cfg.bg, color: cfg.color }}>
      {cfg.label}
    </span>
  );
}

export default function Profile() {
  const { user } = useAuth();

  const [form, setForm] = useState({
    user_prenom: '', user_nom: '', email: '', ville: '', bio: '', telephone: '',
    niveau: '', tarifs_matieres: [], certificats: [], photo_url: null,
    mode_enseignement: 'presentiel', tarif_en_ligne: '', tarif_presentiel: '',
  });
  const [structure, setStructure]         = useState([]);
  const [loading, setLoading]             = useState(true);
  const [saved, setSaved]                 = useState(false);

  // Diplômes
  const [showCertModal, setShowCertModal] = useState(false);
  const [newCert, setNewCert]             = useState({ titre: '' });
  const [selectedFile, setSelectedFile]   = useState(null);

  // Demandes matières
  const [showDemandeModal, setShowDemandeModal] = useState(false);
  const [demandes, setDemandes]                 = useState([]);
  const [newDemande, setNewDemande]             = useState({ nom_matiere: '', niveau_id: '' });
  const [submittingDemande, setSubmittingDemande] = useState(false);
  // Pour pré-remplir le niveau dans la modale si on clique depuis un niveau précis
  const [demandeNiveauPreset, setDemandeNiveauPreset] = useState(null);

  useEffect(() => { fetchProfileData(); }, [user]);

  /* ─── CHARGEMENT ──────────────────────────────────────────────── */
  const fetchProfileData = async () => {
    try {
      let route = '';
      if (user?.role === 'professeur')     route = '/api/professeurs/me';
      else if (user?.role === 'étudiant')  route = '/api/etudiants/me';
      else                                  route = '/api/auth/me';

      const res  = await api.get(route);
      const data = res.data;

      setForm(prev => ({
        ...prev, ...data,
        user_prenom:       data.prenom        || data.user_prenom   || prev.user_prenom,
        user_nom:          data.nom           || data.user_nom      || prev.user_nom,
        ville:             data.ville         || prev.ville,
        telephone:         data.telephone     || prev.telephone,
        bio:               data.bio           || prev.bio,
        niveau:            data.niveau        || prev.niveau,
        email:             data.email         || prev.email,
        certificats:       data.certificats   || prev.certificats,
        tarifs_matieres:   data.tarifs_matieres || prev.tarifs_matieres,
        mode_enseignement: data.mode_enseignement || 'presentiel',
        tarif_en_ligne:    data.tarif_en_ligne   ?? '',
        tarif_presentiel:  data.tarif_presentiel ?? '',
      }));

      if (user?.role === 'professeur') {
        const [resStruct, resDemandes] = await Promise.all([
          api.get('/api/admin/referentiel/structure'),
          api.get('/api/professeurs/me/demandes-matieres'),
        ]);
        setStructure(resStruct.data);
        setDemandes(resDemandes.data);
      }
      setLoading(false);
    } catch (e) {
      console.error('Erreur chargement profil', e);
      setLoading(false);
    }
  };

  /* ─── HELPERS ─────────────────────────────────────────────────── */
  const handleInput = (key, val) => setForm(f => ({ ...f, [key]: val }));

  const isSelected = (matId, nivId) =>
    form.tarifs_matieres?.some(t => t.matiere_id === matId && t.niveau_id === nivId);

  const handleToggleMatiere = (matId, nivId) => {
    let list = [...(form.tarifs_matieres || [])];
    if (isSelected(matId, nivId))
      list = list.filter(t => !(t.matiere_id === matId && t.niveau_id === nivId));
    else
      list.push({ matiere_id: matId, niveau_id: nivId, tarif: 0 });
    setForm(f => ({ ...f, tarifs_matieres: list }));
  };

  /* ─── PHOTO ───────────────────────────────────────────────────── */
  const handlePhotoUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;
    const fd = new FormData();
    fd.append('file', file);
    try {
      const res = await api.post('/api/professeurs/me/photo', fd, {
        headers: { 'Content-Type': 'multipart/form-data' },
      });
      setForm(f => ({ ...f, photo_url: res.data.url }));
      alert('✅ Photo mise à jour !');
    } catch { alert('Erreur photo'); }
  };

  /* ─── CERTIFICAT ──────────────────────────────────────────────── */
  const handleCertUpload = async (e) => {
    e.preventDefault();
    const fd = new FormData();
    fd.append('titre', newCert.titre);
    fd.append('file', selectedFile);
    try {
      await api.post('/api/professeurs/me/certificats', fd, {
        headers: { 'Content-Type': 'multipart/form-data' },
      });
      setShowCertModal(false);
      setNewCert({ titre: '' });
      setSelectedFile(null);
      fetchProfileData();
    } catch { alert('Erreur certificat'); }
  };

  /* ─── DEMANDE MATIÈRE ─────────────────────────────────────────── */
  const openDemandeModal = (niveauId = null) => {
    setNewDemande({ nom_matiere: '', niveau_id: niveauId || '' });
    setDemandeNiveauPreset(niveauId);
    setShowDemandeModal(true);
  };

  const handleSubmitDemande = async (e) => {
    e.preventDefault();
    if (!newDemande.nom_matiere.trim() || !newDemande.niveau_id) {
      alert('Veuillez remplir tous les champs');
      return;
    }
    setSubmittingDemande(true);
    try {
      await api.post('/api/professeurs/me/demandes-matieres', {
        nom_matiere: newDemande.nom_matiere.trim(),
        niveau_id:   parseInt(newDemande.niveau_id),
      });
      alert('✅ Demande envoyée ! L\'administrateur va l\'examiner.');
      setShowDemandeModal(false);
      setNewDemande({ nom_matiere: '', niveau_id: '' });
      // Refresh des demandes
      const res = await api.get('/api/professeurs/me/demandes-matieres');
      setDemandes(res.data);
    } catch (e) {
      alert('Erreur : ' + (e.response?.data?.detail || e.message));
    } finally {
      setSubmittingDemande(false);
    }
  };

  /* ─── SAUVEGARDE ──────────────────────────────────────────────── */
  const handleSave = async () => {
    try {
      let route = '';
      if (user?.role === 'professeur')    route = '/api/professeurs/me';
      else if (user?.role === 'étudiant') route = '/api/etudiants/me';
      else                                 route = '/api/auth/me';

      await api.put(route, {
        nom: form.user_nom, prenom: form.user_prenom,
        ville: form.ville, telephone: form.telephone, bio: form.bio,
        ...(user?.role === 'professeur' && {
          tarifs_complets:   form.tarifs_matieres,
          mode_enseignement: form.mode_enseignement,
          tarif_en_ligne:    form.tarif_en_ligne    !== '' ? parseFloat(form.tarif_en_ligne)    : null,
          tarif_presentiel:  form.tarif_presentiel  !== '' ? parseFloat(form.tarif_presentiel)  : null,
        }),
        ...(user?.role === 'étudiant' && { niveau: form.niveau }),
      });
      setSaved(true);
      setTimeout(() => setSaved(false), 2500);
      alert('✅ Profil enregistré !');
    } catch { alert('Erreur sauvegarde'); }
  };

  /* ─── STYLES ──────────────────────────────────────────────────── */
  const inp = {
    background: 'var(--surface2)', border: '1px solid var(--border)', borderRadius: 10,
    color: 'var(--text)', padding: '10px 14px', fontSize: '.9rem',
    width: '100%', outline: 'none', marginBottom: 15,
  };

  if (loading) return (
    <div style={{ padding: 60, textAlign: 'center', color: 'var(--text2)' }}>
      ⏳ Chargement du profil...
    </div>
  );

  /* ─── RENDU ───────────────────────────────────────────────────── */
  return (
    <div style={{ padding: 32, maxWidth: 1300, margin: '0 auto' }}>

      {/* ── HEADER PHOTO ── */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 30, marginBottom: 32, background: 'var(--card)', padding: 24, borderRadius: 24, border: '1px solid var(--border)' }}>
        <div style={{ position: 'relative' }}>
          <div style={{ width: 110, height: 110, borderRadius: '50%', overflow: 'hidden', border: '3px solid var(--accent)', background: 'var(--surface2)' }}>
            <img
              src={form.photo_url ? `http://localhost:8001${form.photo_url}` : `https://ui-avatars.com/api/?name=${form.user_prenom}`}
              alt="Avatar"
              style={{ width: '100%', height: '100%', objectFit: 'cover' }}
            />
          </div>
          {user?.role === 'professeur' && (
            <label style={{ position: 'absolute', bottom: 5, right: 5, background: 'var(--accent)', width: 32, height: 32, borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer', border: '2px solid var(--card)' }}>
              📷<input type="file" hidden onChange={handlePhotoUpload} />
            </label>
          )}
        </div>
        <div>
          <h2 style={{ fontFamily: 'Syne', fontSize: '1.8rem', margin: 0 }}>{form.user_prenom} {form.user_nom}</h2>
          <p style={{ color: 'var(--text2)', textTransform: 'capitalize', margin: '4px 0 0' }}>Compte {user?.role}</p>
        </div>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: user?.role === 'professeur' ? '420px 1fr' : '1fr', gap: 30 }}>

        {/* ══════════════════════════════════════════════
            COLONNE GAUCHE
        ══════════════════════════════════════════════ */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: 24 }}>

          {/* IDENTITÉ */}
          <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 24 }}>
            <h3 style={{ marginBottom: 20, marginTop: 0 }}>👤 Mon Identité</h3>

            <label style={{ fontSize: '.75rem', color: 'var(--text2)' }}>Prénom</label>
            <input style={inp} value={form.user_prenom} onChange={e => handleInput('user_prenom', e.target.value)} />

            <label style={{ fontSize: '.75rem', color: 'var(--text2)' }}>Nom</label>
            <input style={inp} value={form.user_nom} onChange={e => handleInput('user_nom', e.target.value)} />

            <label style={{ fontSize: '.75rem', color: 'var(--text2)' }}>Email</label>
            <input style={{ ...inp, opacity: 0.6 }} value={form.email} readOnly />

            {user?.role === 'étudiant' && (
              <>
                <label style={{ fontSize: '.75rem', color: 'var(--text2)' }}>Niveau</label>
                <select style={inp} value={form.niveau} onChange={e => handleInput('niveau', e.target.value)}>
                  <option value="">Sélectionner...</option>
                  {NIVEAUX_STUDENT.map(n => <option key={n} value={n}>{n}</option>)}
                </select>
              </>
            )}

            {user?.role !== 'admin' && (
              <>
                <label style={{ fontSize: '.75rem', color: 'var(--text2)' }}>Téléphone</label>
                <input style={inp} value={form.telephone} onChange={e => handleInput('telephone', e.target.value)} />
                <label style={{ fontSize: '.75rem', color: 'var(--text2)' }}>Ville</label>
                <select style={inp} value={form.ville} onChange={e => handleInput('ville', e.target.value)}>
                  <option value="">Sélectionner...</option>
                  {VILLES.map(v => <option key={v} value={v}>{v}</option>)}
                </select>
              </>
            )}

            <button
              onClick={handleSave}
              style={{ width: '100%', background: saved ? '#43e97b' : 'var(--accent)', color: '#fff', border: 'none', padding: 14, borderRadius: 12, fontWeight: 600, cursor: 'pointer', transition: 'background .3s' }}
            >
              {saved ? '✅ Enregistré !' : 'Enregistrer'}
            </button>
          </div>

          {/* BIO */}
          {user?.role === 'professeur' && (
            <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 24 }}>
              <h3 style={{ marginBottom: 12, marginTop: 0 }}>📝 Ma Bio / Méthodologie</h3>
              <textarea
                style={{ ...inp, height: 140, resize: 'none', padding: 14, marginBottom: 0 }}
                value={form.bio || ''}
                placeholder="Ex: Professeur diplômé avec 10 ans d'expérience..."
                onChange={e => handleInput('bio', e.target.value)}
              />
            </div>
          )}

          {/* MODE D'ENSEIGNEMENT */}
          {user?.role === 'professeur' && (
            <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 24 }}>
              <h3 style={{ marginBottom: 6, marginTop: 0 }}>🎓 Mode d'enseignement</h3>
              <p style={{ fontSize: '.8rem', color: 'var(--text2)', marginBottom: 16 }}>
                Choisissez comment vous donnez vos cours, puis précisez votre tarif horaire.
              </p>

              <div style={{ display: 'flex', flexDirection: 'column', gap: 10, marginBottom: 18 }}>
                {MODES.map(m => {
                  const active = form.mode_enseignement === m.value;
                  return (
                    <div
                      key={m.value}
                      onClick={() => handleInput('mode_enseignement', m.value)}
                      style={{ display: 'flex', alignItems: 'center', gap: 14, padding: '13px 16px', borderRadius: 14, cursor: 'pointer', border: active ? '2px solid var(--accent)' : '2px solid var(--border)', background: active ? 'rgba(108,99,255,0.1)' : 'var(--surface2)', transition: 'all .2s' }}
                    >
                      <div style={{ width: 20, height: 20, borderRadius: '50%', border: `2px solid ${active ? 'var(--accent)' : 'var(--text2)'}`, background: active ? 'var(--accent)' : 'transparent', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>
                        {active && <div style={{ width: 8, height: 8, borderRadius: '50%', background: '#fff' }} />}
                      </div>
                      <div>
                        <div style={{ fontWeight: 700, fontSize: '.88rem', color: active ? 'var(--accent)' : 'var(--text)' }}>{m.label}</div>
                        <div style={{ fontSize: '.73rem', color: 'var(--text2)' }}>{m.desc}</div>
                      </div>
                    </div>
                  );
                })}
              </div>

              {/* Tarifs */}
              {(form.mode_enseignement === 'en_ligne' || form.mode_enseignement === 'les_deux') && (
                <div style={{ background: 'rgba(56,189,248,0.07)', border: '1px solid rgba(56,189,248,0.2)', borderRadius: 12, padding: 14, marginBottom: form.mode_enseignement === 'les_deux' ? 12 : 0 }}>
                  <label style={{ fontSize: '.8rem', color: '#38bdf8', fontWeight: 600, display: 'block', marginBottom: 8 }}>🌐 Tarif en ligne (DT/h)</label>
                  <div style={{ display: 'flex', gap: 10, alignItems: 'center' }}>
                    <input type="number" min="0" step="0.5" style={{ ...inp, marginBottom: 0, flex: 1 }} placeholder="Ex: 30" value={form.tarif_en_ligne} onChange={e => handleInput('tarif_en_ligne', e.target.value)} />
                    <span style={{ color: 'var(--text2)', fontWeight: 600, whiteSpace: 'nowrap' }}>DT / h</span>
                  </div>
                </div>
              )}
              {(form.mode_enseignement === 'presentiel' || form.mode_enseignement === 'les_deux') && (
                <div style={{ background: 'rgba(67,233,123,0.07)', border: '1px solid rgba(67,233,123,0.2)', borderRadius: 12, padding: 14 }}>
                  <label style={{ fontSize: '.8rem', color: '#43e97b', fontWeight: 600, display: 'block', marginBottom: 8 }}>🏫 Tarif présentiel (DT/h)</label>
                  <div style={{ display: 'flex', gap: 10, alignItems: 'center' }}>
                    <input type="number" min="0" step="0.5" style={{ ...inp, marginBottom: 0, flex: 1 }} placeholder="Ex: 40" value={form.tarif_presentiel} onChange={e => handleInput('tarif_presentiel', e.target.value)} />
                    <span style={{ color: 'var(--text2)', fontWeight: 600, whiteSpace: 'nowrap' }}>DT / h</span>
                  </div>
                </div>
              )}
            </div>
          )}

          {/* DIPLÔMES */}
          {user?.role === 'professeur' && (
            <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 24 }}>
              <h3 style={{ marginBottom: 14, marginTop: 0 }}>📜 Mes Diplômes</h3>
              <div style={{ display: 'flex', flexDirection: 'column', gap: 8, marginBottom: 12 }}>
                {form.certificats?.map(c => (
                  <div key={c.id} style={{ background: 'var(--surface2)', padding: '10px 14px', borderRadius: 10, border: '1px solid var(--border)', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                    <span style={{ fontWeight: 600, fontSize: '.85rem' }}>{c.titre}</span>
                    <a href={`http://localhost:8001${c.fichier_url}`} target="_blank" rel="noreferrer" style={{ color: 'var(--accent)' }}>👁️</a>
                  </div>
                ))}
                {form.certificats?.length === 0 && (
                  <div style={{ fontSize: '.82rem', color: 'var(--text2)', textAlign: 'center', padding: '12px 0' }}>Aucun diplôme ajouté</div>
                )}
              </div>
              <button onClick={() => setShowCertModal(true)} style={{ width: '100%', border: '2px dashed var(--border)', background: 'none', color: 'var(--accent)', padding: 13, borderRadius: 12, cursor: 'pointer', fontWeight: 600 }}>
                + Ajouter un diplôme
              </button>
            </div>
          )}
        </div>

        {/* ══════════════════════════════════════════════
            COLONNE DROITE : ENSEIGNEMENTS
        ══════════════════════════════════════════════ */}
        {user?.role === 'professeur' && (
          <div style={{ display: 'flex', flexDirection: 'column', gap: 24 }}>

            {/* MATIÈRES */}
            <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 24 }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 20 }}>
                <h3 style={{ margin: 0 }}>📚 Mes Enseignements</h3>
                <button
                  onClick={() => openDemandeModal()}
                  style={{ background: 'rgba(108,99,255,0.12)', color: '#6c63ff', border: '1px solid rgba(108,99,255,0.3)', padding: '7px 14px', borderRadius: 10, cursor: 'pointer', fontWeight: 600, fontSize: '.82rem' }}
                >
                  + Proposer une matière
                </button>
              </div>

              {structure.map(dom => (
                <div key={dom.id} style={{ marginBottom: 32 }}>
                  <div style={{ color: 'var(--accent)', fontWeight: 800, fontSize: '1rem', marginBottom: 14, borderBottom: '2px solid var(--accent)', paddingBottom: 6 }}>
                    📂 {dom.nom.toUpperCase()}
                  </div>

                  {dom.niveaux?.map(niv => (
                    <div key={niv.id} style={{ marginLeft: 12, marginBottom: 20, background: 'var(--surface2)', padding: 18, borderRadius: 16, border: '1px solid var(--border)' }}>

                      {/* Header niveau */}
                      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 12 }}>
                        <div style={{ fontWeight: 700, fontSize: '.95rem' }}>🎓 {niv.nom}</div>
                        <button
                          onClick={() => openDemandeModal(niv.id)}
                          style={{ background: 'none', border: '1px dashed var(--border)', color: 'var(--text2)', padding: '4px 10px', borderRadius: 8, cursor: 'pointer', fontSize: '.72rem', fontWeight: 600 }}
                          title="Proposer une nouvelle matière pour ce niveau"
                        >
                          + matière
                        </button>
                      </div>

                      {/* Grille matières — SANS prix */}
                      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 8 }}>
                        {niv.matieres?.map(mat => {
                          const active = isSelected(mat.id, niv.id);
                          return (
                            <label
                              key={mat.id}
                              style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '9px 13px', borderRadius: 10, cursor: 'pointer', background: active ? 'rgba(108,99,255,0.1)' : 'var(--card)', border: active ? '1px solid rgba(108,99,255,0.4)' : '1px solid transparent', transition: 'all .15s' }}
                            >
                              <input
                                type="checkbox"
                                checked={active}
                                onChange={() => handleToggleMatiere(mat.id, niv.id)}
                                style={{ accentColor: '#6c63ff', width: 15, height: 15, flexShrink: 0 }}
                              />
                              <span style={{ fontSize: '.85rem', fontWeight: active ? 600 : 400, color: active ? 'var(--accent)' : 'var(--text)' }}>
                                {mat.nom}
                              </span>
                            </label>
                          );
                        })}
                      </div>
                    </div>
                  ))}
                </div>
              ))}

              <button
                onClick={handleSave}
                style={{ width: '100%', background: 'var(--accent)', color: '#fff', border: 'none', padding: 13, borderRadius: 12, fontWeight: 600, cursor: 'pointer' }}
              >
                💾 Enregistrer mes enseignements
              </button>
            </div>

            {/* HISTORIQUE DES DEMANDES */}
            {demandes.length > 0 && (
              <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 24 }}>
                <h3 style={{ marginTop: 0, marginBottom: 16 }}>📋 Mes demandes de matières</h3>
                <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
                  {demandes.map(d => (
                    <div key={d.id} style={{ background: 'var(--surface2)', padding: '10px 14px', borderRadius: 10, border: '1px solid var(--border)', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                      <div>
                        <div style={{ fontWeight: 600, fontSize: '.88rem' }}>{d.nom_matiere}</div>
                        <div style={{ fontSize: '.73rem', color: 'var(--text2)', marginTop: 2 }}>Niveau : {d.nom_niveau}</div>
                      </div>
                      <StatutBadge statut={d.statut} />
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>
        )}
      </div>

      {/* ══════════════════════════════════════════════
          MODALE : NOUVEAU DIPLÔME
      ══════════════════════════════════════════════ */}
      {showCertModal && (
        <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.85)', zIndex: 1000, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
          <div style={{ background: 'var(--surface)', padding: 32, borderRadius: 24, width: 440, border: '1px solid var(--border)' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 20 }}>
              <h3 style={{ margin: 0 }}>📁 Nouveau Diplôme</h3>
              <button onClick={() => setShowCertModal(false)} style={{ width: 30, height: 30, borderRadius: 8, background: 'var(--surface2)', border: '1px solid var(--border)', cursor: 'pointer', color: 'var(--text)' }}>✕</button>
            </div>
            <form onSubmit={handleCertUpload} style={{ display: 'flex', flexDirection: 'column', gap: 14 }}>
              <input
                style={inp}
                placeholder="Titre (ex: Master en Informatique)"
                value={newCert.titre}
                onChange={e => setNewCert({ titre: e.target.value })}
                required
              />
              <input type="file" onChange={e => setSelectedFile(e.target.files[0])} required />
              <div style={{ display: 'flex', gap: 10, marginTop: 6 }}>
                <button type="submit" style={{ flex: 2, background: 'var(--accent)', color: '#fff', padding: 12, borderRadius: 10, border: 'none', fontWeight: 700, cursor: 'pointer' }}>Sauvegarder</button>
                <button type="button" onClick={() => setShowCertModal(false)} style={{ flex: 1, background: 'var(--surface2)', color: '#fff', padding: 12, borderRadius: 10, border: 'none', cursor: 'pointer' }}>Annuler</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* ══════════════════════════════════════════════
          MODALE : PROPOSER UNE MATIÈRE
      ══════════════════════════════════════════════ */}
      {showDemandeModal && (
        <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.85)', zIndex: 1000, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
          <div style={{ background: 'var(--surface)', padding: 32, borderRadius: 24, width: 460, border: '1px solid var(--border)' }}>

            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 8 }}>
              <h3 style={{ margin: 0 }}>💡 Proposer une nouvelle matière</h3>
              <button onClick={() => setShowDemandeModal(false)} style={{ width: 30, height: 30, borderRadius: 8, background: 'var(--surface2)', border: '1px solid var(--border)', cursor: 'pointer', color: 'var(--text)' }}>✕</button>
            </div>

            <p style={{ fontSize: '.82rem', color: 'var(--text2)', marginBottom: 20, marginTop: 4 }}>
              Vous ne trouvez pas la matière que vous enseignez ? Proposez-la, l'administrateur l'examinera et l'ajoutera si elle est approuvée.
            </p>

            <form onSubmit={handleSubmitDemande} style={{ display: 'flex', flexDirection: 'column', gap: 14 }}>

              {/* Nom matière */}
              <div>
                <label style={{ fontSize: '.78rem', color: 'var(--text2)', display: 'block', marginBottom: 6, fontWeight: 600 }}>
                  Nom de la matière *
                </label>
                <input
                  style={{ ...inp, marginBottom: 0 }}
                  placeholder="Ex: Robotique, Droit des affaires, Piano..."
                  value={newDemande.nom_matiere}
                  onChange={e => setNewDemande(d => ({ ...d, nom_matiere: e.target.value }))}
                  required
                />
              </div>

              {/* Niveau */}
              <div>
                <label style={{ fontSize: '.78rem', color: 'var(--text2)', display: 'block', marginBottom: 6, fontWeight: 600 }}>
                  Niveau associé *
                </label>
                <select
                  style={{ ...inp, marginBottom: 0 }}
                  value={newDemande.niveau_id}
                  onChange={e => setNewDemande(d => ({ ...d, niveau_id: e.target.value }))}
                  required
                >
                  <option value="">Sélectionner un niveau...</option>
                  {structure.flatMap(dom =>
                    dom.niveaux?.map(niv => (
                      <option key={niv.id} value={niv.id}>
                        [{dom.nom}] {niv.nom}
                      </option>
                    ))
                  )}
                </select>
              </div>

              {/* Info */}
              <div style={{ background: 'rgba(245,158,11,0.08)', border: '1px solid rgba(245,158,11,0.2)', borderRadius: 10, padding: '10px 14px', fontSize: '.78rem', color: '#f59e0b' }}>
                ⚠️ Votre demande sera visible uniquement par l'administrateur. Une fois approuvée, la matière apparaîtra dans le référentiel pour tous.
              </div>

              <div style={{ display: 'flex', gap: 10, marginTop: 4 }}>
                <button
                  type="submit"
                  disabled={submittingDemande}
                  style={{ flex: 2, background: submittingDemande ? 'var(--border)' : 'linear-gradient(135deg,#6c63ff,#8b5cf6)', color: '#fff', padding: 12, borderRadius: 10, border: 'none', fontWeight: 700, cursor: submittingDemande ? 'not-allowed' : 'pointer' }}
                >
                  {submittingDemande ? '⏳ Envoi...' : '📤 Envoyer la demande'}
                </button>
                <button
                  type="button"
                  onClick={() => setShowDemandeModal(false)}
                  style={{ flex: 1, background: 'var(--surface2)', color: '#fff', padding: 12, borderRadius: 10, border: 'none', cursor: 'pointer' }}
                >
                  Annuler
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}
